-- PROMPT 03-A fix, discovered by running the full migration set against a real PostgreSQL
-- instance: a custom GUC like app.tenant_id only reads back as SQL NULL the very first time a
-- session ever touches it. Once any transaction on a pooled connection has SET LOCAL'd it, the
-- reset value on later transactions is empty string, not NULL — so a request that (incorrectly)
-- reaches the database without setting its own tenant context would hit `''::uuid`, which raises
-- "invalid input syntax for type uuid" instead of the intended clean zero-row result. No
-- cross-tenant data is ever exposed either way (a thrown error is not a leak), but NULLIF
-- restores the graceful fail-closed behavior database.md's RLS design already promises. See
-- apps/api/src/database/schema/_policies.ts for the full explanation.
ALTER POLICY "audit_log_tenant_isolation" ON "audit_log" TO app_tenant USING (tenant_id = nullif(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id', true), '')::uuid);--> statement-breakpoint
ALTER POLICY "role_permissions_tenant_isolation" ON "role_permissions" TO app_tenant USING (tenant_id = nullif(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id', true), '')::uuid);--> statement-breakpoint
